import { merge } from 'lodash';
import i18n from '@fiverr/i18n/singleton';
import { loggerListener, statsListener, bigQueryListener, mixpanelListener, logger } from '@fiverr-private/obs';
import routes from '@fiverr-private/pathfinder/routes';
import './index.scss';

/**
 * Loads translations.
 */
const loadTranslations = () => {
    // eslint-disable-next-line no-undef
    i18n.add({ 'en-US': TRANSLATIONS_PLUGIN_KEY });
};

/**
 * Loads routes.
 */
const loadRoutes = () => {
    global.fiverrRoutes = routes;
};

/**
 * The general loaders to be loaded upon each story.
 * @see https://storybook.js.org/docs/react/writing-stories/loaders#global-loaders
 * @type {(function(): Promise)[]}
 */
const loaders = [];

/**
 * The general storybook parameters to be attached on each story.
 * @see https://storybook.js.org/docs/react/writing-stories/parameters#global-parameters
 */
const parameters = {};

/**
 * The general storybook decorators to be attached on each story.
 * @see https://storybook.js.org/docs/react/writing-stories/decorators#global-decorators
 */
let decorators = [];

/**
 * The general storybook args to attach on each story.
 * @see https://storybook.js.org/docs/react/writing-stories/args#global-args
 */
const args = {};

/**
 * The general storybook argTypes to attach on each story.
 * @see https://storybook.js.org/docs/react/api/argtypes
 */
const argTypes = {};

/**
 * The global storybook types.
 * @see https://storybook.js.org/docs/react/essentials/toolbars-and-globals#global-types-and-the-toolbar-annotation
 */
const globalTypes = {};

/**
 * Sets up global storybook.
 * @returns {Promise<void>}
 */
const browserSetup = () => {
    loadTranslations();
    loadRoutes();

    const listenersMode = 'development';

    loggerListener({ logLevel: 'debug', facility: 'storybook', mode: listenersMode });
    statsListener({ mode: listenersMode });
    bigQueryListener({ facility: 'storybook', mode: listenersMode });
    mixpanelListener({ mode: listenersMode });

    // Loading global consumer stories modifiers.
    try {
        const consumerModifiers = require(`${process.env.CWD}/stories`) || {};

        decorators = [...decorators, ...(consumerModifiers.decorators || [])];
        merge(parameters, consumerModifiers.parameters || {});
        merge(args, consumerModifiers.args || {});
        merge(argTypes, consumerModifiers.argTypes || {});
        merge(globalTypes, consumerModifiers.globalTypes || {});
    } catch (error) {
        logger.warn(error);
    }
};

browserSetup();

const preview = {
    decorators,
    parameters,
    loaders,
    args,
    argTypes,
    globalTypes,
};

export default preview;
