import mixpanel from 'mixpanel-browser';

/**
 * A simple class wrapper around Mixpanel's browser API.
 * @property {Object} configuration Configuration.
 * @property {String} configuration.userId The user's ID.
 * @property {String} configuration.userGuid The user's GUID.
 * @property {Object} configuration.baseProperties Base properties to merge with each event.
 * @property {String} configuration.token Mixpanel token.
 * @property {Number} [configuration.recordSessionPercent] Mixpanel record session percentage.
 * @return {Object} Mixpanel decorator.
 */
const Mixpanel = ({ baseProperties = {}, userId, userGuid, token, recordSessionPercent = 0 } = {}) => {
    mixpanel.init(token, {
        disable_persistence: true,
        record_sessions_percent: recordSessionPercent,
        record_mask_text_selector: ''
    });

    if (userGuid) {
        mixpanel.register({
            $device_id: userGuid,
            distinct_id: userGuid
        });
    }

    if (userId) {
        mixpanel.identify(userId);
    }

    const track = (eventName, properties = {}) => {
        const payload = {
            ...baseProperties,
            ...properties
        };

        mixpanel.track(eventName, payload);
    };

    return {
        track
    };
};

export default Mixpanel;
